"""Web notes for Statics CH3–6, following the supplied lecture's section order.
Teaching examples are independent, checked illustrations. The full original
lecture PDFs preserve every original exam question, figure and solution.
"""
CHAPTERS=[]
def chapter(n,title,en,lede):
 CHAPTERS.append(dict(n=n,title=title,en=en,lede=lede,sections=[],examples=[],quiz=[]))
def section(title,text,eqs,points,note='',figures=()):
 CHAPTERS[-1]['sections'].append(dict(title=title,text=text,eqs=eqs,points=points,note=note,figures=figures))
def example(title,q,steps,eqs,answer,figure=None):
 CHAPTERS[-1]['examples'].append(dict(title=title,q=q,steps=steps,eqs=eqs,answer=answer,figure=figure))
def quiz(q,options,answer,why):CHAPTERS[-1]['quiz'].append(dict(q=q,options=options,answer=answer,why=why))

chapter(3,'結構分析','Structural Analysis','從整體自由體圖進入結構內部。先把理想桁架看成二力構件，再用節點法、截面法與零力構件規則求桿力，最後分解構架與機具。')
section('簡單桁架',['桁架由直桿在端點連接而成，簡單平面桁架可由一個三角形開始，每次增加一個節點與兩根桿件。理想模型假設接頭無摩擦、負載作用於節點，桿件只承受沿軸線的拉力或壓力。','桿件若只在兩端受力且沒有力偶，平衡要求兩力大小相等、方向相反、作用線重合。因此可用一個軸力未知數描述每根二力桿。負載若作用在桿中間，該桿就不能直接當成理想二力桿。'],[(r'm+r=2j','平面桁架的靜定計數條件；m為桿數、r為外反力分量、j為節點數'),(r'N>0\;\mathrm{(tension)},\quad N<0\;\mathrm{(compression)}','先假設拉力，負值代表壓力')],['先畫整體自由體圖並求支承反力。','檢查接頭與負載是否符合桁架理想化。','計數符合靜定條件後，仍須檢查幾何穩定與反力是否獨立。'],'桿數與方程式數目相同，不保證結構穩定；幾何排列也可能形成機構。',('truss','twoforce'))
section('桁架分析',['節點法將單一節點分離，所有桿力都沿桿軸作用。每個平面節點提供兩個獨立力平衡式，宜從未知桿力不超過兩個的節點開始。計算出的桿力須以相反方向放到相鄰節點。','截面法適合只求少數指定桿力：假想切開結構，取其中一側列兩個力平衡式與一個力矩平衡式。對另兩個未知桿力作用線的交點取矩，常能直接求出目標桿力。','零力規則須先檢查節點是否真的沒有外力，包括支承反力。無外力且僅接兩根不共線桿時，兩桿皆為零力；無外力的三桿節點若兩桿共線，第三桿為零力。辨認後可逐步移除零力桿再檢查其他節點。'],[(r'\sum F_x=0,\quad\sum F_y=0','平面節點的兩個獨立平衡式'),(r'\sum F_x=0,\quad\sum F_y=0,\quad\sum M_O=0','截開後的一側視為平面剛體')],['先標示零力構件，再選擇節點法或截面法。','截面法通常選切過不超過三個獨立未知桿力的截線。','取矩點不一定要在被保留的結構上。','以另一節點或整體平衡回算，檢查拉壓與數值。'],'有四根以上桿件的節點，不能只因其中兩根共線就判定其餘桿件皆為零力。',('joint','zero','section'))
section('構架與機具',['構架含有至少一根承受三個以上作用力的構件，常同時存在軸力、剪力與彎矩。機具利用各構件的相對運動傳遞或放大作用力，分析時仍需針對平衡位置列自由體圖。','先辨認真正的二力連桿，再逐件分離。銷接點在相鄰構件上出現大小相等、方向相反的接點力；取整體時，這些內部接點力互相抵銷。','如果構件為非平行三力構件，三力作用線必須共點。這個幾何條件可以簡化方向判斷，但仍須用平衡求力的大小。'],[(r'\mathbf F_{A\to B}=-\mathbf F_{B\to A}','接點力遵守作用與反作用'),(r'\sum M_O=0','取銷接點為矩心可消去該點兩個未知力分量')],['先求整體反力，再拆分構件。','每個構件都要包含其自身外力、重量與接點力。','找出二力構件，利用其軸線決定端點力方向。','最後核對每一構件的平衡。'],'接點力在整體自由體圖中是內力；拆成單一構件時則是外力。',('frame','lever'))
example('三角桁架的桿力','A(0,0)、B(6,0)、C(3,4)組成三角桁架，座標單位為公尺。A為鉸支承，B為滾支承，C受10 kN鉛直向下力。求三桿軸力。',['整體取矩與鉛直平衡，得到兩支承各5 kN向上，水平反力為零。','兩斜桿長5 m，因此鉛直、水平分量係數分別為4/5與3/5。','在C節點先假設兩斜桿受拉，所得負值表示受壓；再由A節點求底桿。'],[(r'A_y=B_y=5\ \mathrm{kN},\quad A_x=0',''),(r'-2N_{AC}\frac45-10=0\Rightarrow N_{AC}=N_{BC}=-6.25\ \mathrm{kN}','由對稱性兩斜桿力相同'),(r'N_{AB}=6.25\frac35=3.75\ \mathrm{kN}','')],'兩斜桿各承受6.25 kN壓力，底桿承受3.75 kN拉力。','triangle-example')
example('零力構件的判定','某節點有三根桿件相接，其中兩根水平共線，第三根鉛直。節點沒有外加力，也不是支承點。第三根桿力為何？若此點另受向下5 kN力，結果如何？',['沒有外力時，鉛直平衡只有第三根桿的鉛直分量，所以其軸力為零。','若增加5 kN向下力，第三根桿就必須提供5 kN向上力，原本的零力結論不再成立。'],[(r'N_{\mathrm{vertical}}=0\quad\mathrm{(no\ external\ load)}',''),(r'F_{\mathrm{vertical\ member}}=5\ \mathrm{kN}\quad\mathrm{(upward)}','加入向下負載之後')],'零力構件是特定負載狀態下的結論，不能脫離節點外力條件使用。')
example('截面法直接求底弦力','桁架節點A(0,0)、B(4,0)、C(8,0)、D(4,3)，桿件為AB、BC、AD、DC及BD。A鉸支、C滾支，B承受12 kN向下力。用截面法求AB。',['由整體平衡得A與C反力各6 kN。','在A與B之間切過AB及AD，取含A的左側自由體圖。','對D取矩，AD的作用線通過D而不產生力矩，AB的力臂為3 m。'],[(r'3N_{AB}-6(4)=0','拉力假設使AB向右'),(r'N_{AB}=8\ \mathrm{kN}','')],'AB承受8 kN拉力；不必先解出其餘全部桿力。','section-example')
example('構架中的二力連桿','水平桿AB長3 m，A為鉸支承；B以鉛直連桿BC連到上方固定點C。AB在距A點1 m處受6 kN向下力，自重忽略。求BC軸力及A反力。',['BC無中途負載，因此是二力構件，對B只提供鉛直力。','對AB的A點取矩，再列鉛直與水平平衡。'],[(r'3N_{BC}-6(1)=0\Rightarrow N_{BC}=2\ \mathrm{kN}',''),(r'A_y=6-2=4\ \mathrm{kN},\quad A_x=0','')],'連桿BC受拉2 kN，A點向上反力4 kN。','frame-example')
example('理想鉗子的力放大','對稱鉗子每側手柄各受100 N，手力到轉銷的垂直力臂為200 mm，鉗口力的垂直力臂為40 mm。忽略摩擦與自重，求每側鉗口力。',['分離其中一側鉗臂，以共同轉銷取矩。','另一側由對稱性得到相同大小的鉗口力；兩鉗口在工件上方向相反。'],[(r'100(200)-F(40)=0\Rightarrow F=500\ \mathrm N','')],'每側鉗口力500 N。工件兩側受到一對500 N夾力，不能把它們當成同方向的1000 N合力。')
quiz('下列哪一項最符合理想桁架的基本假設？',['所有桿件都承受彎矩','外力作用於節點，接頭無摩擦','桿件可在中點任意受力而仍為二力桿','桿力必定為拉力'],1,'理想桁架的節點受力與無摩擦鉸接，使各直桿可以視為二力構件。')
quiz('無外力的三桿節點中，兩桿共線，第三桿不共線。第三桿的軸力為何？',['零','等於兩共線桿之和','必定受壓','無法由節點平衡判斷'],0,'沿垂直於共線桿的方向列平衡，第三桿分量必須為零。')
quiz('截面法對另兩個未知桿力作用線的交點取矩，主要目的是什麼？',['令全部桿力為零','消去這兩個未知力的力矩','改變支承反力','省略整體平衡'],1,'通過矩心的作用力力矩為零，留下目標桿力及已知力。')
quiz('對構架中的內部銷接點，哪個敘述正確？',['每個構件上的接點力方向相同','整體圖仍須畫兩組同方向接點力','相鄰構件上的接點力大小相等、方向相反','銷接點必定不傳力'],2,'拆分時須成對畫作用與反作用；合成整體後，內力互相抵銷。')

chapter(4,'摩擦','Friction','先以平衡求出所需摩擦力，再檢查接觸面能否提供。分清靜摩擦上限與實際值，並比較滑動、傾倒、斜面及梯子的平衡條件。')
section('摩擦的種類',['接觸面上的摩擦力沿切線方向，阻止兩接觸面之間的相對滑動或滑動趨勢。摩擦方向須依局部接觸面的相對運動判斷，不一定與物體整體的運動方向相反。','乾摩擦也稱庫侖摩擦，理想模型把最大靜摩擦及動摩擦與正向力連結；有潤滑液的流體摩擦與材料變形造成的內部摩擦，則須使用不同模型。','物體仍靜止時，靜摩擦可從零調整到極限；超過極限後發生滑動，通常改採動摩擦模型。滾動阻力的物理來源與滑動摩擦不同，不宜直接套成同一常數。'],[],['先確認是否接觸；分離的表面不能提供正向力或乾摩擦。','判斷各接觸點的相對滑動趨勢。','尚未滑動、即將滑動與已滑動，使用不同的摩擦條件。'],'摩擦係數受材料、表面與接觸狀況影響；不能把「與表觀面積無關」當成所有情況的普遍定律。',('friction-curve',))
section('摩擦的定律',['先假設物體靜止，由力與力矩平衡求所需摩擦力及正向力，再檢查摩擦上限。只有在確定即將滑動時，才把靜摩擦寫成上限等式。','斜向拉力可能降低正向力，向下推力則可能增加正向力，因此不能一律把正向力當成重量。多接觸面應逐一寫摩擦限制，只有確實達臨界的接觸面才能取等號。','高物塊承受水平推力時，也可能先繞底邊傾倒。應同時計算滑動門檻與傾倒門檻，再比較何者先到達；接觸反力作用點會隨推力移動。'],[(r'|F_s|\leq\mu_sN,\quad N\geq0','靜止接觸的可行範圍'),(r'|F_s|=\mu_sN','即將滑動的臨界狀態'),(r'|F_k|=\mu_kN','已滑動時的庫侖動摩擦近似'),(r'P_{\mathrm{slide}}=\mu_sW,\quad P_{\mathrm{tip}}=\frac{Wb}{2h}','水平力作用於高度h，物塊底寬b，重心位於寬度中央')],['畫自由體圖，假設摩擦方向並列平衡。','計算正向力，檢查是否仍接觸。','檢查所需摩擦是否超過上限。','同時檢查反力作用點是否仍在接觸面內。'],'若算出所需摩擦超過上限，表示靜止假設不成立，不能硬把該力值當成實際摩擦力。',('friction-block','tipping','ladder'))
section('摩擦角與靜止角',['接觸總反力由正向力與摩擦力合成。總反力與接觸法線的夾角在臨界滑動時達到摩擦角；仍能靜止時，總反力方向應位於摩擦角界限內。','只有重量作用於斜面上物塊、且忽略其他外力時，逐漸增加坡度直到剛要下滑，該坡角稱為靜止角，與摩擦角相等。若另有推力、拉力或加速度，不能直接使用這個等同關係。','對斜面上的平行外力，分別假設即將上滑與即將下滑，就能求出保持靜止的外力範圍；兩端的摩擦方向恰好相反。'],[(r'R=\sqrt{N^2+F_s^2},\quad\tan\phi_s=\mu_s','摩擦角由最大靜摩擦決定'),(r'\theta_{\mathrm{repose}}=\tan^{-1}\mu_s','僅受重力的斜面物塊'),(r'W\sin\theta-\mu_sW\cos\theta\leq P\leq W\sin\theta+\mu_sW\cos\theta','P沿斜面向上，且正向力僅由重力決定')],['沿斜面及垂直斜面選座標。','平衡範圍的上下界分別使用相反的臨界摩擦方向。','把求得的外力代回平衡式，確認摩擦方向與大小。'],'靜止角的簡式有特定負載條件，不能直接用在有額外外力的斜面問題。',('incline','friction-angle'))
example('摩擦力不是固定等於上限','重500 N的物塊放在水平面，靜摩擦係數0.30。先施加100 N水平拉力，再增加為180 N。分別判斷能否保持靜止。',['水平面上的正向力等於500 N。','先求最大靜摩擦，再與平衡所需摩擦比較。'],[(r'F_{s,\max}=0.30(500)=150\ \mathrm N',''),(r'P=100\ \mathrm N\Rightarrow F_s=100\ \mathrm N<150\ \mathrm N',''),(r'P=180\ \mathrm N>150\ \mathrm N','無可行的靜止平衡')],'100 N時摩擦力為100 N且保持靜止；180 N時會滑動，實際動摩擦大小仍需另知動摩擦係數。')
example('斜面上可保持靜止的推力範圍','重1000 N的物塊置於30°斜面，靜摩擦係數0.40。外力P沿斜面向上，求保持靜止的P範圍。',['正向力由垂直斜面平衡求出。','最低推力對應即將下滑，摩擦向上；最高推力對應即將上滑，摩擦向下。'],[(r'N=1000\cos30^{\circ}=866.03\ \mathrm N',''),(r'P_{\min}=500-0.40(866.03)=153.59\ \mathrm N',''),(r'P_{\max}=500+0.40(866.03)=846.41\ \mathrm N','')],'推力介於153.59 N與846.41 N之間時可保持靜止，端點為臨界狀態。')
example('光滑牆面與粗糙地面的梯子','均勻梯長5 m、重200 N，梯腳距光滑牆3 m，梯頂高4 m。求地面所需摩擦力及最小靜摩擦係數。',['牆面光滑，只提供水平反力；地面提供鉛直正向力與水平摩擦。','梯重作用在中點，對梯腳的水平力臂為1.5 m。','對梯腳取矩，消去地面兩個未知分量。'],[(r'4N_B-200(1.5)=0\Rightarrow N_B=75\ \mathrm N',''),(r'F_A=75\ \mathrm N,\quad N_A=200\ \mathrm N',''),(r'\mu_{s,\min}=\frac{75}{200}=0.375','')],'地面摩擦力為75 N、方向朝牆；靜摩擦係數至少0.375。','ladder-example')
example('先滑動還是先傾倒','重600 N的均勻長方物塊底寬0.60 m，以高度1.0 m的水平推力作用，地面靜摩擦係數0.40。推力緩慢增加，哪種失效先發生？',['滑動門檻由最大靜摩擦決定。','傾倒門檻以靠推力方向的底邊為支點取矩。'],[(r'P_{\mathrm{slide}}=0.40(600)=240\ \mathrm N',''),(r'P_{\mathrm{tip}}=\frac{600(0.60)}{2(1.0)}=180\ \mathrm N','')],'180 N先到達傾倒門檻；此時所需摩擦180 N仍小於240 N上限。')
example('水平物塊連接懸掛重物','水平面上60 kg物塊A，以輕繩跨過無摩擦固定滑輪，連到懸掛物塊B。靜摩擦係數0.20，求B可保持靜止的最大質量。',['B靜止時繩張力等於B重量。','A的正向力等於A重量；臨界狀態下張力等於最大靜摩擦。'],[(r'm_Bg\leq\mu_sm_Ag','兩物塊都必須靜止'),(r'm_B\leq0.20(60)=12\ \mathrm{kg}','')],'B最大質量12 kg；等號是即將滑動的臨界值。','hanging')
quiz('物塊受水平100 N外力仍保持靜止，而最大靜摩擦為150 N，實際摩擦力為何？',['0 N','100 N','150 N','必須先知道動摩擦係數'],1,'靜摩擦先由平衡決定，最大值只是其上限。')
quiz('物塊在水平面上受到斜向上的拉力，正向力通常如何改變？',['必定等於重量','因拉力向上分量而減少','增加為重量與全部拉力之和','必定變成零'],1,'只要仍接觸，正向力由鉛直平衡求得；向上的拉力分量抵銷部分重量。')
quiz('只有重量作用的物塊，在何種斜面角度達到剛要下滑？',['坡角正切等於靜摩擦係數','坡角正弦等於動摩擦係數','坡角必定為45°','坡角與摩擦無關'],0,'臨界時沿坡向重力分量等於最大靜摩擦，故坡角正切等於靜摩擦係數。')
quiz('判斷高物塊受水平推力時的臨界狀態，應如何處理？',['只算滑動即可','只算傾倒即可','比較滑動與傾倒兩個門檻','直接把所有接觸點的摩擦都設成上限'],2,'較小的門檻先到達；還須同時確認摩擦與接觸條件。')

chapter(5,'質心、形心及慣性矩','Centroids and Area Moments','用一次矩求形心，再以二次矩描述面積分布。透過組合面積、孔洞與平行軸定理，建立截面係數及迴轉半徑，銜接材料力學的彎曲與柱分析。')
section('重心、形心與質量中心',['重心是重力合力的作用位置；質量中心由質量分布決定；形心則只與幾何分布有關。均勻重力場中，重心與質量中心重合。均質、等厚平板的質量中心又與面積形心重合。','非均質材料不能只用面積加權；應把密度與厚度納入質量。對稱性可直接決定部分座標，亦可用來檢查計算結果。'],[(r'\bar x_m=\frac{\sum m_ix_i}{\sum m_i},\quad\bar y_m=\frac{\sum m_iy_i}{\sum m_i}','離散質點的質量中心'),(r'\bar x_A=\frac1A\int_A x\,dA,\quad\bar y_A=\frac1A\int_A y\,dA','平面面積形心')],['先判斷是求重量、質量、線長、面積或體積的中心。','選同一原點與座標方向。','使用對應的權重作一次矩加總。'],'中空或凹形物體的形心可以位於沒有材料的位置。',('centroid',))
section('各類重（形）心求法',['組合面積可拆成已知形心的基本圖形，孔洞則視為負面積。所有子圖形的位置都要相對同一原點，且避免面積重複加計。','線形構件以線長加權，薄板以面積加權，立體以體積加權。對圓弧與圓面，雖然輪廓相似，權重不同會得到不同的形心。','不規則面積可取微小面積條積分；若使用鉛直條，條的形心高度不是上緣高度，而是該條上下邊界的平均位置。'],[(r'\bar x=\frac{\sum A_ix_i}{\sum A_i},\quad\bar y=\frac{\sum A_iy_i}{\sum A_i}','孔洞以負面積處理'),(r'\bar y_{\mathrm{arc}}=\frac{2R}{\pi},\quad\bar y_{\mathrm{semicircle}}=\frac{4R}{3\pi}','半圓弧線與半圓面積，從直徑量起'),(r'\bar y_{\mathrm{triangle}}=\frac h3','三角形面積形心，從底邊量起')],['列出每一塊的面積、形心座標及面積一次矩。','孔洞的面積與一次矩同時取負。','最後確認形心是否符合對稱性及幾何範圍。'],'圓弧線形心不可直接套用半圓面積公式。',('composite','semicircle','l-section'))
section('慣性矩與極慣性矩',['面積慣性矩以每一小面積至指定軸的距離平方加權，決定截面對該方向的抗彎幾何能力。其單位為長度四次方，與動力學使用的質量慣性矩不同。','平行軸定理以形心軸為基準：偏移到另一條平行軸時，增加面積乘軸距平方。組合截面先求總形心，再將各子面積的慣性矩移至共同軸後加減。','極慣性矩相對於垂直平面的軸定義，等於平面內兩條互相垂直軸的面積慣性矩之和。對非圓截面，面積極慣性矩不一定等於扭轉常數。'],[(r'I_x=\int_A y^2\,dA,\quad I_y=\int_A x^2\,dA','面積慣性矩'),(r'J_O=\int_A(x^2+y^2)\,dA=I_x+I_y','同一交點的極慣性矩'),(r'I=I_c+Ad^2','從形心軸移至距離d的平行軸'),(r'I_{x,\mathrm{rectangle}}=\frac{bh^3}{12},\quad I_{y,\mathrm{rectangle}}=\frac{hb^3}{12}','矩形形心軸'),(r'I_{\mathrm{circle}}=\frac{\pi D^4}{64},\quad J_{\mathrm{circle}}=\frac{\pi D^4}{32}','實心圓的形心軸與中心極軸')],['先畫所求軸，明確量出垂直距離。','自身慣性矩與平行軸項都要對孔洞作扣除。','求極慣性矩時，兩個平面軸必須通過同一點。'],'平行軸定理中的自身慣性矩須相對形心軸，不能任意用兩條非形心軸互相加減同一項。',('inertia','t-section','hollow'))
section('截面係數與迴轉半徑',['截面係數將慣性矩除以最外纖維到指定形心軸的距離，方便比較彎曲強度。上下不對稱截面應分別求上、下緣截面係數。','迴轉半徑把分散的面積等效集中到一個離軸距離；它是幾何量，常用於柱的細長比。計算時必須說明相對哪一條軸。'],[(r'S_x=\frac{I_x}{c_y},\quad S_y=\frac{I_y}{c_x}','本頁以S表示彈性截面係數，原講義亦使用Z'),(r'r_x=\sqrt{\frac{I_x}{A}},\quad r_y=\sqrt{\frac{I_y}{A}}','面積迴轉半徑'),(r'\sigma_{\max}=\frac{|M|}{S},\quad\lambda=\frac{KL}{r}','與材料力學的彎曲應力及柱細長比連結')],['截面係數的單位為長度三次方。','迴轉半徑的單位為長度。','旋轉矩形截面後，面積相同，但對固定水平軸的慣性矩會改變。'],'不對稱截面不能只算一個截面係數就當成上下緣皆相同。',('section-modulus',))
example('離散質點的質量中心','2 kg質點在(0,0)，3 kg質點在(4,0)，5 kg質點在(0,6)，座標單位為公尺。求質量中心。',['先求總質量10 kg。','分別對水平、鉛直座標作質量加權。'],[(r'\bar x=\frac{2(0)+3(4)+5(0)}{10}=1.2\ \mathrm m',''),(r'\bar y=\frac{2(0)+3(0)+5(6)}{10}=3.0\ \mathrm m','')],'質量中心位於(1.2 m, 3.0 m)。')
example('L形截面的形心','外框寬80 mm、高100 mm，挖去右上角寬60 mm、高80 mm的矩形，留下底板及左側直板，厚度皆20 mm。以左下角為原點，求面積形心。',['將剩餘截面拆成80×20底板，以及其上方20×80直板，兩塊不重疊。','底板形心為(40,10)，直板形心為(10,60)，面積各1600 mm²。'],[(r'A=1600+1600=3200\ \mathrm{mm^2}',''),(r'\bar x=\frac{1600(40)+1600(10)}{3200}=25\ \mathrm{mm}',''),(r'\bar y=\frac{1600(10)+1600(60)}{3200}=35\ \mathrm{mm}','')],'形心為(25 mm, 35 mm)，位於L形缺口之內也是合理的。','l-section')
example('T形截面的形心與慣性矩','T形截面上翼板100×20 mm，腹板20×80 mm，總高100 mm。以底部為高度原點，求形心高度與水平形心軸慣性矩。',['翼板面積2000 mm²、形心高度90 mm；腹板面積1600 mm²、形心高度40 mm。','先求共同形心，再將兩塊的自身慣性矩移至共同水平軸。'],[(r'\bar y=\frac{2000(90)+1600(40)}{3600}=67.778\ \mathrm{mm}',''),(r'I_x=I_{\mathrm{flange}}+I_{\mathrm{web}}','對同一條水平形心軸加總'),(r'I_{\mathrm{flange}}=\frac{100(20)^3}{12}+2000(90-\bar y)^2','翼板部分'),(r'I_{\mathrm{web}}=\frac{20(80)^3}{12}+1600(40-\bar y)^2','腹板部分'),(r'I_x=3.14222\times10^6\ \mathrm{mm^4}','')],'形心距底部67.778 mm，水平形心軸慣性矩約3.14222×10⁶ mm⁴。','t-section')
example('半圓弧線與半圓面積','半徑60 mm的均勻半圓細線，以及同半徑的均勻等厚半圓薄板，各自形心距直徑多遠？',['兩者都有鉛直對稱軸，水平形心在圓心正上方。','細線使用線長權重，薄板使用面積權重。'],[(r'\bar y_{\mathrm{wire}}=\frac{2(60)}{\pi}=38.20\ \mathrm{mm}',''),(r'\bar y_{\mathrm{area}}=\frac{4(60)}{3\pi}=25.46\ \mathrm{mm}','')],'細線形心較高，距直徑38.20 mm；薄板形心距直徑25.46 mm。')
example('中空圓截面的慣性矩','同心圓管外徑80 mm、內徑40 mm，求水平形心軸慣性矩及中心極慣性矩。',['孔洞視為負面積，且內、外圓形心重合，因此不需要平移項。','兩個互相垂直的直徑軸慣性矩相同。'],[(r'I_x=\frac{\pi(80^4-40^4)}{64}=1.88496\times10^6\ \mathrm{mm^4}',''),(r'J=2I_x=3.76991\times10^6\ \mathrm{mm^4}','')],'面積慣性矩約1.88496×10⁶ mm⁴，極慣性矩約3.76991×10⁶ mm⁴。','hollow')
example('矩形截面的截面係數與迴轉半徑','矩形寬40 mm、高80 mm，求水平形心軸的慣性矩、截面係數及迴轉半徑。若軸向上平移20 mm，該平行軸的慣性矩為何？',['垂直於水平軸的高度取三次方。','截面係數使用最外纖維距離40 mm；迴轉半徑使用總面積3200 mm²。','最後以平行軸定理求偏移軸慣性矩。'],[(r'I_x=\frac{40(80)^3}{12}=1.70667\times10^6\ \mathrm{mm^4}',''),(r'S_x=\frac{I_x}{40}=42666.7\ \mathrm{mm^3},\quad r_x=\sqrt{\frac{I_x}{3200}}=23.094\ \mathrm{mm}',''),(r'I_{\mathrm{shifted}}=I_x+3200(20)^2=2.98667\times10^6\ \mathrm{mm^4}','')],'截面係數42666.7 mm³、迴轉半徑23.094 mm；偏移軸慣性矩約2.98667×10⁶ mm⁴。')
quiz('均質等厚平板的面積形心與質量中心有何關係？',['必定分離','互相重合','只對圓形重合','必定位於外輪廓上'],1,'均質且等厚時，質量與面積成正比，因此兩種加權給出相同中心。')
quiz('計算挖孔截面的形心時，孔洞應如何處理？',['只扣面積，不扣一次矩','面積與面積一次矩都取負','面積取正、位置取零','直接忽略孔洞'],1,'孔洞是被移除的面積，其面積及相對原點的一次矩都應扣除。')
quiz('面積慣性矩、截面係數與迴轉半徑的單位依序為何？',['長度、長度平方、長度三次方','質量、力、長度','長度四次方、長度三次方、長度','三者都沒有單位'],2,'從定義可見，面積慣性矩為面積乘距離平方；後兩者分別再除距離及開平方。')
quiz('對矩形水平形心軸的慣性矩，哪一個尺寸被取三次方？',['沿軸的寬度','垂直於軸的高度','兩個尺寸都取三次方','與截面方向無關'],1,'面積離水平軸的距離沿高度方向變化，因此矩形公式中高度取三次方。')

chapter(6,'虛功與最小位能原理','Virtual Work and Potential Energy','利用符合約束的假想微小位移建立平衡。再把保守力寫成位能，分辨平衡位置與穩定平衡，補上原講義最後一章。')
section('虛功原理',['虛位移是在固定時刻、符合幾何約束的假想微小位移。系統可以完全靜止，仍能用虛位移判斷作用力是否平衡；虛位移不是實際運動的時間歷程。','對理想約束系統，若作用力對所有容許虛位移所作的總虛功為零，即滿足靜力平衡。光滑接觸的法向反力通常與容許虛位移垂直，因此不作虛功；固定鉸支點沒有位移，也不作虛功。','先選廣義座標，把各受力點的位置寫成該座標的函數，再微分得到相互受約束的虛位移。不能把各受力點的位移當作互相獨立。'],[(r'\delta W=\sum_i\mathbf F_i\cdot\delta\mathbf r_i+\sum_i M_i\delta\theta_i=0','平面系統；力矩與虛轉角採相同正號'),(r'\delta x_i=\frac{dx_i}{dq}\delta q,\quad\delta y_i=\frac{dy_i}{dq}\delta q','單自由度系統的位移相容'),(r'\sum_i\left(F_{xi}\frac{dx_i}{dq}+F_{yi}\frac{dy_i}{dq}+M_i\frac{d\theta_i}{dq}\right)=0','消去任意的共同虛位移')],['選出能描述構形的最少廣義座標。','建立受力點的位置與幾何約束。','對座標微分，確認每個力的虛功正負。','列總虛功為零，再用自由體圖平衡交叉檢查。'],'摩擦力可能作虛功，不可只因它是接觸力就省略。只對一個任意試探方向作功為零，也不一定代表所有自由度都平衡。',('virtual-rod','pulley'))
section('最小位能原理',['對重力、彈簧力等保守力系統，可建立總位能函數。平衡位置是位能的駐值點；穩定平衡則對應局部最小位能，不穩定平衡可能對應最大位能。','單自由度系統在平衡點的二階導數為正時是穩定，為負時是不穩定。二階導數為零時，還須看高階項或整段位能形狀，不能立即判為中性平衡。','多自由度系統須對每個獨立座標的偏導數皆為零；穩定性則檢查位能二階變分或Hessian矩陣是否正定。摩擦等非保守作用通常不能只靠一個簡單位能函數處理。'],[(r'V=V_g+V_e,\quad V_g=Wy,\quad V_e=\frac12kx^2','重力高度與彈簧變形的基準須一致'),(r'\frac{dV}{dq}=0','單自由度的平衡條件'),(r'\left.\frac{d^2V}{dq^2}\right|_{q_0}>0\;\mathrm{stable},\quad\left.\frac{d^2V}{dq^2}\right|_{q_0}<0\;\mathrm{unstable}','一般非退化平衡點'),(r'\frac{\partial V}{\partial q_i}=0\quad(i=1,\ldots,n)','多自由度平衡條件')],['把所有保守力的位能相加。','先求駐值點，再評估穩定性。','檢查座標範圍、接觸及支承條件是否可行。'],'「平衡」與「最小位能」不是同義詞。例如四次方位能在原點二階導數為零，仍可有穩定最小值。',('potential','rod-spring'))
example('光滑牆角的均勻桿','長L、重200 N的均勻桿，上端靠光滑鉛直牆，下端置光滑水平地面。桿與水平夾45°，在下端施加朝牆的水平力P使其平衡。求P。',['以桿角度為廣義座標，下端離牆距離為L乘角度餘弦，重心高度為半桿長乘角度正弦。','P朝牆，重力向下；對各自位置變化作虛功。','牆與地面的正向反力不作虛功。'],[(r'x_B=L\cos\theta,\quad y_G=\frac L2\sin\theta',''),(r'-P\delta x_B-W\delta y_G=0',''),(r'PL\sin\theta-\frac{WL}{2}\cos\theta=0',''),(r'P=\frac W2\cot\theta=100\ \mathrm N','')],'所需朝牆水平力100 N；也可對梯腳取矩驗證。','virtual-rod')
example('動滑輪的力與位移關係','理想單動滑輪以兩段鉛直繩支承900 N負載，繩、滑輪無重且無摩擦。求自由端所需拉力，以及負載上升10 mm時自由端拉出的繩長。',['繩總長不變，負載上升一段距離，兩段支承繩各縮短相同距離。','自由端拉出長度為負載上升量兩倍，再列輸入力與重量的虛功。'],[(r'\delta s=2\delta h,\quad P\delta s-W\delta h=0',''),(r'P=\frac W2=450\ \mathrm N,\quad s=20\ \mathrm{mm}','')],'拉力450 N，自由端拉出20 mm；省力的代價是較大的輸入位移。','pulley')
example('垂直彈簧的穩定平衡','重50 N物體懸在剛度200 N/m的垂直線性彈簧下方，以向下伸長x為座標，求平衡伸長並判斷穩定性。',['彈簧位能為伸長平方的一半剛度倍；向下移動會減少重力位能。','先令位能一階導數為零，再檢查二階導數。'],[(r'V(x)=\frac12kx^2-Wx',''),(r'\frac{dV}{dx}=kx-W=0\Rightarrow x=\frac{50}{200}=0.25\ \mathrm m',''),(r'\frac{d^2V}{dx^2}=k=200\ \mathrm{N/m}>0','')],'平衡伸長0.25 m，為穩定平衡。')
example('有平衡解不代表穩定','均勻桿長2 m、重200 N，構形由與水平夾角描述。水平彈簧剛度100 N/m，彈簧伸長等於桿長乘角度餘弦；90°時不受力。求0°～90°內平衡位置並判斷穩定性。',['建立彈簧位能與重心重力位能。','位能一階導數包含角度餘弦因子，因此不能直接約掉而漏掉90°解。','對每個候選平衡位置檢查二階導數。'],[(r'V=\frac12kL^2\cos^2\theta+\frac{WL}{2}\sin\theta',''),(r'\frac{dV}{d\theta}=\cos\theta\left(\frac{WL}{2}-kL^2\sin\theta\right)=0',''),(r'\theta=30^{\circ}\;\mathrm{or}\;90^{\circ}',''),(r'V^{\prime\prime}(30^{\circ})=-300\ \mathrm{J/rad^2}<0','30度為不穩定'),(r'V^{\prime\prime}(90^{\circ})=200\ \mathrm{J/rad^2}>0','90度為穩定')],'30°雖滿足平衡，但不是位能最小值；在此理想模型與可行構形下，90°才是穩定平衡。','rod-spring')
quiz('虛位移的正確敘述為何？',['必定是物體實際移動的距離','是不受任何約束的任意位移','是在固定時刻符合約束的假想微小位移','必定與每個外力平行'],2,'虛位移用於測試平衡，必須符合接觸、桿長及支承等幾何約束。')
quiz('光滑接觸面的法向反力，何時不作虛功？',['反力數值為零時才不作功','容許虛位移沿接觸切線、與法向反力垂直時','任何接觸力都永遠不作功','只要物體有重量就不作功'],1,'虛功是力與虛位移的內積，互相垂直時為零。')
quiz('位能一階導數為零，可以直接得到哪個結論？',['必定穩定','必定不穩定','是候選平衡位置，穩定性還須檢查','必定為中性平衡'],2,'位能駐值可能是極小、極大或退化點，需進一步檢查。')
quiz('平衡點的位能二階導數為零，應如何處理？',['立即判定中性平衡','立即判定沒有平衡','檢查高階項或完整位能形狀','改用最大靜摩擦公式'],2,'例如正四次方函數在原點二階導數為零，卻仍為穩定的嚴格最小值。')
